def solve():
    for n in range(1, 101):
        s = 0
        for a in range(1, n + 1):
            for b in range(1, n + 1):
                s += (a * b) // (n + 1)

        target = (n**3 - n**2 + 2) / 4
        if s == target:
            print(f"N={n}, Sum={s}, Target={target}")

